def once_twice(nums):
    # Count the frequency of each number
    freq = {}
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Collect elements that appear once
    result = []
    for num, count in freq.items():
        if count == 1:
            result.append(num)

    # Return the sorted result
    return sorted(result)
